// Function to find the roots of a quadratic equation
// Given the equation: f(x) = x^2 + 2x + 1
// Returns the roots of the equation in a vector
function find_roots(f) {
    // Compute the discriminant
    var discriminant = f[2] * f[2] - 4 * f[1] * f[0];

    // Check if discriminant is positive, negative, or zero
    if (discriminant > 0) {
        var x1 = (-f[1] + Math.sqrt(discriminant)) / (2 * f[0]);
        var x2 = (-f[1] - Math.sqrt(discriminant)) / (2 * f[0]);
